// Die Instanzwerte kommen aus sub-einstellungen (Knoten davor) und werden
// in der Data Table pw_config gepflegt (n8n-Oberfläche, "Data Tables").
// HIER stehen nur die FACHLICHEN Einstellungen dieses Workflows: Fristen,
// Tag-Namen, Feldnamen.
const werte = $('Einstellungen holen').first().json;
const pw = (key) => {
  const v = werte[key];
  if (v === undefined || String(v).trim() === '') {
    throw new Error('pw_config: "' + key + '" fehlt oder ist leer; in der n8n-Oberfläche unter "Data Tables" eintragen.');
  }
  return v;
};
// fallback_email: Empfänger für Dokumente ohne Eigentümer oder wenn der
// Paperless-Benutzer keine E-Mail hinterlegt hat. Das ist genau die
// Betriebsadresse, deshalb derselbe Schlüssel wie überall sonst.
return [{
  json: {
    // ── aus der Data Table pw_config ──
    paperless_url:             pw('paperless_url'),
    paperless_url_oeffentlich: pw('paperless_url_oeffentlich'),
    absender:                  pw('mail_absender'),
    fallback_email:            pw('mail_betrieb'),

    // ── fachlich, hier zu pflegen ──
    // feld_erinnerung: Name des Paperless-Custom-Fields mit dem Erinnerungsdatum.
    feld_erinnerung: 'Erinnern am'
  }
}];

// Feld-ID auflösen und die Abfrage bauen: fällig ist alles mit
// "Erinnern am" <= heute (auch Überfälliges wird gemeldet).
const cfg = $('Konfiguration').first().json;
const fields = $json.results || [];

const feld = fields.find(f => String(f.name).toLowerCase() === cfg.feld_erinnerung.toLowerCase());
if (!feld) {
  throw new Error('Custom Field "' + cfg.feld_erinnerung + '" existiert nicht in Paperless; bitte anlegen (Typ Datum) oder Konfiguration anpassen.');
}

const today = new Date().toISOString().slice(0, 10);
const customFieldQuery = JSON.stringify([cfg.feld_erinnerung, 'lte', today]);

return [{ json: Object.assign({}, cfg, { feld_erinnerung_id: feld.id, customFieldQuery }) }];

// Dokumente nach Eigentümer gruppieren, pro Eigentümer eine Mail.
// Dokumente ohne Eigentümer landen in einer eigenen Gruppe (ownerId: null)
// und bekommen weiter unten die fallback_email.
const docs = $json.results || [];
const groups = new Map();
for (const doc of docs) {
  const key = doc.owner ?? 'keiner';
  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push(doc);
}

return Array.from(groups.entries()).map(([key, docs]) => ({
  json: { ownerId: key === 'keiner' ? null : key, docs }
}));

// E-Mail-Adresse aus dem Paperless-Benutzer lesen. Fail-soft: wurde der
// Benutzer gelöscht (404) oder hat keine E-Mail hinterlegt, greift die Fallback-Adresse.
const cfg = $('Konfiguration').first().json;
const group = $('Loop über Eigentümer').item.json;
const user = $input.first().json;

const email = (user && !user.error && typeof user.email === 'string' && user.email.trim()) ? user.email.trim() : null;
const toEmail = email || cfg.fallback_email;
const toName = (user && !user.error && (user.first_name || user.username))
  ? (user.first_name ? (user.first_name + (user.last_name ? ' ' + user.last_name : '')) : user.username)
  : 'Team';

return [{ json: { toEmail, toName, docs: group.docs } }];

// Dokumente ohne Eigentümer bekommen die Fallback-Adresse aus der Konfiguration.
const cfg = $('Konfiguration').first().json;
const group = $('Loop über Eigentümer').item.json;

return [{ json: { toEmail: cfg.fallback_email, toName: 'Team', docs: group.docs } }];

// HTML-Mail für einen Eigentümer (oder die Fallback-Adresse) aufbauen.
const cfg = $('Konfiguration').first().json;
const { toEmail, toName, docs } = $json;

if (!toEmail || String(toEmail).indexOf('@') === -1) {
  throw new Error('Keine gültige Empfänger-Adresse ermittelt (weder Benutzer-E-Mail noch fallback_email gesetzt).');
}

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = (iso) => iso ? new Date(iso).toLocaleDateString('de-DE') : '-';
const valErinnerung = (doc) => {
  const cf = (doc.custom_fields || []).find(f => f.field === cfg.feld_erinnerung_id);
  return cf && cf.value ? fmt(cf.value) : '-';
};

const rows = docs.map(doc => {
  const docUrl = cfg.paperless_url_oeffentlich + '/documents/' + doc.id + '/detail';
  return '<tr>'
    + '<td style="padding:6px 12px;border:1px solid #ddd;"><a href="' + docUrl + '" style="color:#1a73e8;">' + esc(doc.title || '(kein Titel)') + '</a></td>'
    + '<td style="padding:6px 12px;border:1px solid #ddd;color:#c0392b;font-weight:bold;">' + valErinnerung(doc) + '</td>'
    + '</tr>';
}).join('\n');

const today = new Date().toLocaleDateString('de-DE', { timeZone: 'Europe/Berlin' });
const anzahl = docs.length + (docs.length === 1 ? ' Dokument' : ' Dokumente');

const html = '<div style="font-family:Arial,sans-serif;max-width:700px;">'
  + '<h2 style="color:#2c3e50;border-bottom:2px solid #2c3e50;padding-bottom:8px;">Erinnerung</h2>'
  + '<p>Hallo ' + esc(toName) + ',</p>'
  + '<p>f\u00fcr <strong>' + anzahl + '</strong> ist eine Erinnerung f\u00e4llig:</p>'
  + '<table cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:14px;width:100%;margin:16px 0;">'
  + '<thead><tr style="background:#2c3e50;color:#fff;"><th style="padding:10px 12px;text-align:left;">Dokument</th><th style="padding:10px 12px;text-align:left;">Erinnern am</th></tr></thead>'
  + '<tbody>' + rows + '</tbody></table>'
  + '<p style="font-size:13px;color:#555;">Nach Erledigung das Feld \u201eErinnern am\u201c im Dokument leeren oder auf ein neues Datum setzen \u2014 sonst kommt morgen wieder eine Erinnerung.</p>'
  + '<p><a href=' + cfg.paperless_url_oeffentlich + ' style="background:#2c3e50;color:#fff;padding:8px 16px;text-decoration:none;border-radius:4px;display:inline-block;">&#8594; Paperless-NGX \u00f6ffnen</a></p>'
  + '<p style="color:#95a5a6;font-size:12px;margin-top:32px;border-top:1px solid #eee;padding-top:12px;">Automatisch generiert am ' + today + ' \u00b7 <a href="https://github.com/paper-werk">Paper-Werk</a></p>'
  + '</div>';

return [{ json: { html, toEmail, subject: 'Erinnerung: ' + anzahl, absender: cfg.absender } }];
